"""Bundle seed_data.ts + core.ts + enter_ai.ts + server.ts into one self-contained index.ts.

The Enter-managed edge runtime deploys the entry file; a single file with no imports is the most portable.
Run from this folder:  python bundle.py
"""
import re
from pathlib import Path

HERE = Path(__file__).resolve().parent
parts = ["seed_data.ts", "core.ts", "enter_ai.ts", "server.ts"]
out = [
    "// GENERATED by bundle.py from seed_data.ts, core.ts, enter_ai.ts and server.ts. Edit those, then re-run.",
    "// deno-lint-ignore-file no-explicit-any",
    "/* eslint-disable @typescript-eslint/no-explicit-any */",
    "",
]
for name in parts:
    src = (HERE / name).read_text(encoding="utf-8")
    src = re.sub(r"^import .*?;\s*$", "", src, flags=re.M)          # drop local imports
    src = re.sub(r"^// deno-lint-ignore-file.*$", "", src, flags=re.M)
    src = re.sub(r"^/\* eslint-disable .*\*/\s*$", "", src, flags=re.M)
    src = re.sub(r"^export (?=(const|function|async function|class|interface|type) )", "", src, flags=re.M)
    out += [f"// ---------------------------------------------------------------- {name}", src.strip(), ""]
(HERE / "index.ts").write_text("\n".join(out) + "\n", encoding="utf-8")
print("wrote index.ts,", sum(len(x) for x in out), "chars")
